"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { X } from "lucide-react";

export default function AddressFormDrawer({ isOpen, onClose, onSave, initialData }: any) {
  const [formData, setFormData] = useState<any>(initialData || {
    pincode: "", city: "", area: "", landmark: "", building: "", recipientName: "", primaryPhone: "+91 ", altPhone: "+91 "
  });
  const [errors, setErrors] = useState<any>({});

  // Logic to show State and District based on Pincode
  const getRegion = (pin: string) => {
    if (pin.length === 6) {
      // In a real app, this would be an API call to a postal service
      return "KERALA, MALAPPURAM"; 
    }
    return "Waiting for Pincode...";
  };

  const validate = () => {
    let e: any = {};
    if (formData.pincode.length !== 6) e.pincode = true;
    if (!formData.city) e.city = true;
    if (!formData.area) e.area = true;
    if (!formData.building) e.building = true;
    if (!formData.recipientName) e.recipientName = true;
    if (formData.primaryPhone.replace(/\D/g, "").length < 10) e.primaryPhone = true;
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          {/* Backdrop */}
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }} 
            onClick={onClose} 
            className="fixed inset-0 bg-foreground/20 backdrop-blur-md z-[60]" 
          />

          {/* Drawer */}
          <motion.div 
            initial={{ y: "100%" }} 
            animate={{ y: 0 }} 
            exit={{ y: "100%" }} 
            transition={{ type: "spring", damping: 30, stiffness: 300 }} 
            className="fixed bottom-0 left-0 right-0 bg-background rounded-t-[3rem] z-[70] shadow-2xl max-w-3xl mx-auto border-t border-border flex flex-col max-h-[92vh]"
          >
            {/* Header: Non-sticky */}
            <div className="flex justify-between items-center p-8 md:p-12 pb-6">
              <div>
                <h2 className="text-2xl font-black uppercase tracking-tighter italic">Address Details</h2>
                <p className="text-[10px] font-bold text-foreground-muted uppercase tracking-[0.2em] mt-1">Delivery Destination</p>
              </div>
              <button onClick={onClose} className="p-3 bg-background-muted rounded-full hover:rotate-90 transition-transform">
                <X size={20} />
              </button>
            </div>

            {/* Scrollable Form Body */}
            <div className="flex-1 overflow-y-auto px-8 md:px-12 pb-4 custom-scrollbar">
              <form className="space-y-8">
                
                {/* Row 1: Pincode & Region */}
                <div className="grid grid-cols-2 gap-4">
                  <InputWrapper 
                    label="Pincode" 
                    value={formData.pincode} 
                    onChange={(v: string) => setFormData({...formData, pincode: v.slice(0,6)})} 
                    placeholder="6 Digits" 
                    type="number"
                    error={errors.pincode}
                  />
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-foreground-muted uppercase tracking-[0.2em] px-4">Detected Region</label>
                    <div className="w-full bg-background-muted/20 border-2 border-border border-dotted rounded-2xl p-4 h-[58px] flex items-center text-[11px] font-black uppercase tracking-widest text-foreground-muted">
                      {getRegion(formData.pincode)}
                    </div>
                  </div>
                </div>

                {/* Row 2: City & Area (Single Row) */}
                <div className="grid grid-cols-2 gap-4">
                  <InputWrapper 
                    label="City / Town" 
                    value={formData.city} 
                    onChange={(v: string) => setFormData({...formData, city: v})} 
                    placeholder="e.g. Puthanathani" 
                    error={errors.city}
                  />
                  <InputWrapper 
                    label="Area / Locality" 
                    value={formData.area} 
                    onChange={(v: string) => setFormData({...formData, area: v})} 
                    placeholder="Street/Colony" 
                    error={errors.area}
                  />
                </div>

                {/* Row 3: Building & Landmark (Single Row) */}
                <div className="grid grid-cols-2 gap-4">
                  <InputWrapper 
                    label="Building / House No" 
                    value={formData.building} 
                    onChange={(v: string) => setFormData({...formData, building: v})} 
                    placeholder="No. / Name" 
                    error={errors.building}
                  />
                  <InputWrapper 
                    label="Landmark" 
                    value={formData.landmark} 
                    onChange={(v: string) => setFormData({...formData, landmark: v})} 
                    placeholder="Famous place" 
                    required={false}
                  />
                </div>

                <div className="h-[1px] bg-border border-dashed border-t w-full opacity-30 my-2" />

                {/* Recipient Details */}
                <InputWrapper 
                  label="Recipient Name" 
                  value={formData.recipientName} 
                  onChange={(v: string) => setFormData({...formData, recipientName: v})} 
                  placeholder="Full name" 
                  error={errors.recipientName}
                />

                <div className="grid grid-cols-2 gap-4">
                  <InputWrapper 
                    label="Primary Phone" 
                    value={formData.primaryPhone} 
                    onChange={(v: string) => setFormData({...formData, primaryPhone: v})} 
                    placeholder="+91" 
                    error={errors.primaryPhone}
                  />
                  <InputWrapper 
                    label="Alt Phone" 
                    value={formData.altPhone} 
                    onChange={(v: string) => setFormData({...formData, altPhone: v})} 
                    placeholder="Optional" 
                    required={false}
                  />
                </div>
              </form>
            </div>

            {/* Sticky Footer Button */}
            <div className="p-8 md:px-12 border-t border-border bg-background/80 backdrop-blur-xl">
              <button 
                type="button" 
                onClick={() => validate() && onSave(formData)} 
                className="w-full bg-foreground text-background py-6 rounded-full font-black uppercase tracking-[0.2em] text-xs shadow-2xl active:scale-95 transition-transform"
              >
                Save Shipping Address
              </button>
            </div>

          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
}

// Reusable Small Input Component
function InputWrapper({ label, value, onChange, placeholder, type = "text", required = true, error = false }: any) {
  return (
    <div className="space-y-2">
      <div className="flex justify-between px-4">
        <label className="text-[9px] font-black text-foreground-muted uppercase tracking-[0.2em]">{label}</label>
      </div>
      <input 
        type={type}
        value={value} 
        onChange={(e) => onChange(e.target.value)} 
        placeholder={placeholder} 
        className={`w-full bg-transparent border-2 ${error ? 'border-red-500' : 'border-border'} border-dotted rounded-2xl p-4 focus:border-foreground outline-none transition-all font-bold text-sm placeholder:text-foreground-subtle/20 placeholder:font-medium`} 
      />
    </div>
  );
}